    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xA083408507D15629ULL + 0xDAD3C14BDD039A73ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xF45E92321B3E941BULL + 0xE69A3E5738A8F8F6ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0x903CC635BB3A5E7DULL + 0xDCC8B3602EE598B1ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xF4B78A093D6A0167ULL + 0xD8BD4746189E1008ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xDCCB16BEB6B364F9ULL + 0xB43AC1FCD0E1A5ECULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0xAC5D8884458C5549ULL + 0xC92242F3A9A59627ULL);
