    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0x8324C4F6BAA4A56DULL + 0xCACBADEF6F06AB14ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0x8C31EEBCB2132C1FULL + 0xC652E7B41214B738ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseB(pNonce * 0xA501743C7F64E71FULL + 0xAF57D006F3204D6CULL);
