            aOrbiterD = RotL64((aOrbiterD * 0x953CB9502E0A89FDULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x5D2A58C3CE0281F8ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterC) ^ 0x3517B176E03034E4ULL) ^ aOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xB1A6C5649B160AA1ULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xE044DA36766566D3ULL;
