            aOrbiterG = RotL64((aOrbiterG * 0x42AF37489BF69A4BULL), 43U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xA7AE24C218FA3941ULL;
            aOrbiterA = (((aOrbiterA ^ aOrbiterJ) ^ 0xCDD38FDA7F4E3BA0ULL) ^ aOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1]) ^ aNonceWordF;
            aOrbiterA = RotL64((aOrbiterA * 0xF7D6872186C5DEF1ULL), 11U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x58EF7E6B1DC04D69ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xB9AF3A7B99F5A97DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0E7A9E3EE4154397ULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x881B0551BB35F35DULL) + aNonceWordD;
