            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xB56FE1BD4FDE6586ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0xDC491A6CE5BC871FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x36245359592DDC85ULL), 21U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x685F33462AF1D9CFULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x8619B1330A64A129ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x135D63E0F3B224E1ULL), 23U);
            //
            aIngress = RotL64(aOrbiterD, 13U) ^ aOrbiterB;
