            aWandererK = aWandererK ^ (((RotL64(aIngress, 21U) + RotL64(aOrbiterA, 51U)) + aOrbiterI) + aWandererUpdateSaltB[((aIndex + 10U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aScatter, 29U) + RotL64(aOrbiterD, 35U)) + aOrbiterG);
