            aOrbiterC = (aWandererB + RotL64(aScatter, 35U)) + 0xF54865F416E58784ULL;
            aOrbiterG = (aWandererD + RotL64(aPrevious, 47U)) + 0xE1E56161AB22B48EULL;
            aOrbiterB = (((aWandererJ + RotL64(aIngress, 23U)) + RotL64(aCarry, 47U)) + 0xB0922F0471398E1CULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
