            aOrbiterG = RotL64((aOrbiterG * 0x3D3914D239092823ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0xC5E9FAA860FA5BCFULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x3F39A7E75EE9DFDCULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xE0CDC0B4F8EEDB47ULL), 41U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterH) + 0x84DDCB84AB67D62FULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 24U)) & S_SALT1];
