            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x6599D34EDCBCD896ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0x9DCEF60CCB63EAB7ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 7U)) & S_SALT1];
