            aWandererE = aWandererE + (((RotL64(aCross, 14U) + aOrbiterH) + RotL64(aOrbiterD, 11U)) + aTwistWandererUpdateSaltE[((aIndex + 12U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterB, 58U)) + aOrbiterE);
