            aOrbiterG = ((aWandererG + RotL64(aIngress, 34U)) + 0x7D67F159F7128312ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterE = (aWandererJ + RotL64(aScatter, 23U)) + 0x9559D26625897C0BULL;
