            aOrbiterB = (aWandererI + RotL64(aCross, 4U)) + 0xA676538A37B3AA34ULL;
            aOrbiterK = (((aWandererF + RotL64(aPrevious, 39U)) + RotL64(aCarry, 47U)) + 0x80F22CD3369D8E7EULL) + aTwistOrbiterAssignSaltC[((aIndex + 14U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aIngress, 57U)) + RotL64(aCarry, 37U)) + 0x46BD69F5B4A07072ULL;
            aOrbiterA = (aWandererK + RotL64(aCross, 51U)) + 0xB1AB4F0EBCC1B355ULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x5FD038C37E8A1252ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x3E392A24F43A36E6ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xEC1A85B335D35597ULL), 23U);
