            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x55D799AEE9178351ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x547103615EC5F226ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x0265B60F183D9DC1ULL), 3U);
