            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x390C4B2AA7509404ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0x5E77BCDA2CDDDFC1ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x4E456D8487EC3717ULL), 37U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x2BE0CB37BF7BA47FULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0xB139B9A8EF888C05ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
