            aWandererB = aWandererB ^ (((RotL64(aIngress, 53U) + RotL64(aOrbiterI, 39U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1]);
