            aOrbiterB = (((aWandererF + RotL64(aIngress, 57U)) + RotL64(aCarry, 27U)) + 0x6B7E5F9C34A8EA4FULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
