            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0x58251EB3437113CEULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x9228A1CD638C4B99ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x4FDFBA6DDE55BC19ULL), 29U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0x9DD6A872E985D3BAULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
