            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xDBBBC442482CED63ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0xEDF7AD5618722662ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
